-- Restore semester-3 chemistry curriculum and the preserved legacy physiology tests.
-- Source: public_html SpaceWeb archive (curriculum_master.json and legacy/tests/mc/*).
BEGIN;

WITH subject AS (
  SELECT id FROM public.subjects
  WHERE slug = 'chemistry_organic_physical' AND course_number = 2 AND semester = 3 AND is_active = true
  ORDER BY id LIMIT 1
),
seed(week_no, legacy_key, date_label, lecture, practice, study) AS (
  VALUES
    (1, 'chemistry-sem3-week-01', '02.09', 'Лек 1: Введение. Предмет органической химии. Классификация. Номенклатура. Изомерия.', 'Лаба 1: Введение в практикум. Классификация, номенклатура.', 'Органическая химия. Основной курс. Часть 1: Глава 1. Классификация и номенклатура органических соединений (п. 1.1. Классификация, п. 1.2. Общие положения номенклатуры ИЮПАК, п. 1.3. Принципы построения систематических названий). Лабораторные работы по органической химии: Раздел 1. Правила работы и техника безопасности в лаборатории органической химии. Раздел 2. Химическая посуда и лабораторное оборудование. Сборник задач...: Раздел 1. Теоретические основы органической химии. Приложения 1, 2, 3.'),
    (2, 'chemistry-sem3-week-02', '09.09', 'Лек 2: Пространственное строение. Конформация. Цис-транс. Оптическая изомерия.', 'Лаба 2: Пространственная изомерия.', 'Органическая химия. Основной курс. Часть 1: Глава 4. Стереоизомерия органических молекул (п. 4.1. Способы изображения пространственного строения молекул, п. 4.2. Конфигурационные стереоизомеры, п. 4.3. Конформации, п. 4.4. Пространственное строение молекул и их биологическая активность). Лабораторные работы по органической химии: Раздел 3. Методы выделения, очистки веществ и определение основных физических констант.'),
    (3, 'chemistry-sem3-week-03', '16.09', 'Лек 3: Химическая связь. Электронные эффекты. Механизмы реакций.', 'Лаба 3: Химическая связь. Электронные эффекты.', 'Органическая химия. Основной курс. Часть 1: Глава 2. Химические связи и взаимное влияние атомов в органических соединениях (п. 2.1. Локализованная химическая связь, п. 2.2. Делокализованная химическая связь, п. 2.3. Взаимное влияние атомов в молекулах и способы его передачи). Глава 3. Классификация реакций органических соединений (п. 3.1. Типы органических реакций и реагентов, п. 3.2. Представления о механизме реакции). Сборник задач...: Приложения 5, 6.'),
    (4, 'chemistry-sem3-week-04', '23.09', 'Лек 4: Физико-химические методы (УФ-, ИК-, ЯМР-, масс-спектрометрия).', 'Лаба 4: Сравнительная оценка кислотных и основных свойств.', 'Органическая химия. Основной курс. Часть 1: Глава 5. Кислотные и основные свойства органических соединений (п. 5.1. Кислотность и основность по Брёнстеду-Лоури, п. 5.2. Кислоты и основания Льюиса). Лабораторные работы по органической химии: Раздел 5. Сравнительная оценка кислотных и основных свойств (Опыты 5.1–5.6).'),
    (5, 'chemistry-sem3-week-05', '30.09', 'Лек 5: Углеводороды. Механизмы радикального и электрофильного замещения.', 'КР №1: Теоретические основы органической химии.', 'Сборник задач...: Раздел 1. Теоретические основы органической химии (стр. 5–20). Тестовые задания.'),
    (6, 'chemistry-sem3-week-06', '07.10', 'Лек 6: Арены (Строение, получение, свойства).', 'Лаба 6: Физико-химические методы (Спектроскопия).', 'Лабораторные работы по органической химии: Раздел 4. Физико-химические методы исследования органических соединений (п. 4.1. УФ-спектроскопия, п. 4.2. ИК-спектроскопия, п. 4.3. ЯМР-спектроскопия).'),
    (7, 'chemistry-sem3-week-07', '14.10', 'Лек 7: Галогенопроизводные углеводородов. Механизмы SN.', 'Лаба 7: Предельные и непредельные углеводороды.', 'Органическая химия. Основной курс. Часть 1: Глава 6. Алканы. Глава 7. Циклоалканы. Глава 8. Алкены. Глава 9. Алкадиены. Глава 10. Алкины. Лабораторные работы по органической химии: Раздел 6. Получение и реакционная способность предельных и непредельных углеводородов (Опыты 6.1–6.5).'),
    (8, 'chemistry-sem3-week-08', '21.10', 'Лек 8: Гидроксисоединения (Спирты, Фенолы, Енолы, Эфиры).', 'Лаба 8: Арены.', 'Органическая химия. Основной курс. Часть 1: Глава 12. Ароматические углеводороды (арены) (п. 12.1–12.6). Лабораторные работы по органической химии: Раздел 7. Получение и свойства ароматических углеводородов (Опыты 7.1–7.5).'),
    (9, 'chemistry-sem3-week-09', '28.10', 'Лек 9: Оксосоединения (Альдегиды и кетоны).', 'КР №2: Углеводороды.', 'Сборник задач...: Раздел 2. Углеводороды. Моно- и гетерофункциональные соединения (стр. 21–41). Тестовые задания.'),
    (10, 'chemistry-sem3-week-10', '04.11', 'Лек 10: Карбоновые кислоты. Классификация.', 'Лаба 10: Галогенопроизводные углеводородов.', 'Органическая химия. Основной курс. Часть 1: Глава 13. Галогеноуглеводороды (п. 13.1–13.6). Лабораторные работы по органической химии: Раздел 8. Получение и свойства галогеноуглеводородов (Опыты 8.1–8.5).'),
    (11, 'chemistry-sem3-week-11', '11.11', 'Лек 11: Одноатомные и многоатомные спирты.', 'Лаба 11: Спирты.', 'Органическая химия. Основной курс. Часть 1: Глава 14. Спирты (п. 14.1–14.6). Лабораторные работы по органической химии: Раздел 9. Свойства одноатомных и многоатомных спиртов (Опыты 9.1–9.6).'),
    (12, 'chemistry-sem3-week-12', '18.11', 'Лек 12: Фенолы. Простые эфиры.', 'Лаба 12: Фенолы. Простые эфиры.', 'Органическая химия. Основной курс. Часть 1: Глава 15. Фенолы (п. 15.1–15.6). Глава 16. Простые эфиры (п. 16.1–16.7). Лабораторные работы по органической химии: Раздел 10. Свойства фенолов (Опыты 10.1–10.4). Раздел 11. Получение и реакционная способность простых эфиров (Опыты 11.1–11.3).'),
    (13, 'chemistry-sem3-week-13', '25.11', 'Лек 13: Контрольная работа № 3.', 'КР №3: Спирты, фенолы и простые эфиры.', 'Сборник задач...: Раздел 2. Углеводороды. Моно- и гетерофункциональные соединения (стр. 21–41). Тестовые задания.'),
    (14, 'chemistry-sem3-week-14', '02.12', 'Лек 14: Альдегиды. Кетоны. Реакции AN, AN-E.', 'Лаба 14: Альдегиды и кетоны.', 'Органическая химия. Основной курс. Часть 1: Глава 18. Альдегиды и кетоны (п. 18.1–18.6). Лабораторные работы по органической химии: Раздел 12. Реакционная способность альдегидов и кетонов (Опыты 12.1–12.9).'),
    (15, 'chemistry-sem3-week-15', '09.12', 'Лек 15: Монокарбоновые кислоты. Получение, свойства.', 'Лаба 15: Монокарбоновые кислоты.', 'Органическая химия. Основной курс. Часть 1: Глава 19. Карбоновые кислоты (п. 19.1–19.6). Лабораторные работы по органической химии: Раздел 13. Химические свойства карбоновых кислот и их производных (Опыты 13.1–13.10).'),
    (16, 'chemistry-sem3-week-16', '16.12', 'Лек 16: Дикарбоновые кислоты.', 'Лаба 16: Дикарбоновые кислоты.', 'Органическая химия. Основной курс. Часть 1: Глава 19. Карбоновые кислоты (разделы по дикарбоновым кислотам). Лабораторные работы по органической химии: Раздел 13 (продолжение). Раздел 14. Получение и свойства гетерофункциональных карбоновых кислот: галогено-, гидрокси-, оксокислот (Опыты 14.1–14.5).'),
    (17, 'chemistry-sem3-week-17', '23.12', 'Лек 17: Контрольная работа № 4.', 'КР №4: Альдегиды, кетоны, карбоновые кислоты.', 'Сборник задач...: Раздел 2. Углеводороды. Моно- и гетерофункциональные соединения (стр. 21–41). Тестовые задания.'),
    (18, 'chemistry-sem3-week-18', '30.12', 'Лек 18: Зачётное занятие.', 'Лаба 18: Зачётное занятие.', 'Повторить весь пройденный материал по всем трем учебникам.')
)
INSERT INTO public.curriculum_items
  (subject_id, course_number, semester, item_type, title, description, order_index, is_required, is_active, source, metadata)
SELECT s.id, 2, 3, 'lecture', seed.lecture, seed.study, seed.week_no, true, true,
  'spaceweb:curriculum_master',
  jsonb_build_object('legacy_key', seed.legacy_key, 'date', seed.date_label, 'week', seed.week_no,
    'lecture', seed.lecture, 'practice', seed.practice, 'study', seed.study, 'source_file', 'data/curriculum_master.json')
FROM public.subjects s CROSS JOIN seed
WHERE s.slug = 'chemistry_organic_physical' AND s.course_number = 2 AND s.semester = 3 AND s.is_active = true
  AND NOT EXISTS (SELECT 1 FROM public.curriculum_items ci WHERE ci.subject_id = s.id AND ci.metadata->>'legacy_key' = seed.legacy_key);

WITH subject AS (
  SELECT id FROM public.subjects WHERE slug = 'physiology' AND course_number = 2 AND semester = 3 AND is_active = true ORDER BY id LIMIT 1
),
test_seed(source_key,title,order_index) AS (
  VALUES
    ('spaceweb:physiology-physio-blood', 'Кровь — базовый', 1),
    ('spaceweb:physiology-physio-cardio', 'Кровообращение — базовый', 2)
),
seeded_tests AS (
  INSERT INTO public.tests(subject_id,title,time_limit_sec,max_attempts,is_published,source_key,order_index)
  SELECT s.id, t.title, 600, NULL, true, t.source_key, t.order_index FROM subject s CROSS JOIN test_seed t
  ON CONFLICT (subject_id,source_key) WHERE source_key IS NOT NULL
  DO UPDATE SET title=EXCLUDED.title, is_published=true, archived_at=NULL, order_index=EXCLUDED.order_index
  RETURNING id,source_key
),
question_seed(test_source_key,source_key,prompt,options,answer,correct_index,order_index,topic) AS (
  VALUES
    ('spaceweb:physiology-physio-blood','spaceweb:physiology:pb1','Норма гемоглобина у женщин примерно:','["70–90 г/л","120–140 г/л","180–200 г/л","40 г/л"]'::jsonb,'120–140 г/л',1,1,'Кровь'),
    ('spaceweb:physiology-physio-blood','spaceweb:physiology:pb2','Эритроциты переносят O₂ за счёт:','["инсулина","гемоглобина","фибрина","альбумина"]'::jsonb,'гемоглобина',1,2,'Кровь'),
    ('spaceweb:physiology-physio-blood','spaceweb:physiology:pb3','Лейкоциты отвечают за:','["свёртывание","иммунную защиту","транспорт O₂","онкотическое давление"]'::jsonb,'иммунную защиту',1,3,'Кровь'),
    ('spaceweb:physiology-physio-cardio','spaceweb:physiology:pc1','Нормальный сердечный ритм в покое около:','["40/мин","60–80/мин","140/мин","20/мин"]'::jsonb,'60–80/мин',1,1,'Сердечно-сосудистая система'),
    ('spaceweb:physiology-physio-cardio','spaceweb:physiology:pc2','Систола желудочков выбрасывает кровь в:','["только вены","аорту и лёгочный ствол","предсердия","капилляры напрямую"]'::jsonb,'аорту и лёгочный ствол',1,2,'Сердечно-сосудистая система'),
    ('spaceweb:physiology-physio-cardio','spaceweb:physiology:pc3','Водитель ритма в норме:','["пучок Гиса","синоатриальный узел","АВ-узел только","Пуркинье"]'::jsonb,'синоатриальный узел',1,3,'Сердечно-сосудистая система'),
    ('spaceweb:physiology-physio-cardio','spaceweb:physiology:pc4','Артериальное давление 120/80: первое число —','["диастола","систола","среднее","пульсовое"]'::jsonb,'систола',1,4,'Сердечно-сосудистая система')
),
seeded_questions AS (
  INSERT INTO public.questions(subject_id,type,text,answer,options,is_published,source_key)
  SELECT s.id, 'mcq'::public.question_type, q.prompt, q.answer, q.options, true, q.source_key
  FROM subject s CROSS JOIN question_seed q
  ON CONFLICT (subject_id,source_key) WHERE source_key IS NOT NULL
  DO UPDATE SET text=EXCLUDED.text,answer=EXCLUDED.answer,options=EXCLUDED.options,is_published=true,archived_at=NULL
  RETURNING id,source_key
)
INSERT INTO public.test_questions(test_id,question_id,order_index)
SELECT st.id,sq.id,qs.order_index
FROM question_seed qs JOIN seeded_questions sq ON sq.source_key=qs.source_key
JOIN seeded_tests st ON st.source_key=qs.test_source_key
ON CONFLICT (test_id,question_id) DO UPDATE SET order_index=EXCLUDED.order_index;

COMMIT;
